// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "Test", "TST"); }
    function testFuzz_property(uint256 initialBalance, uint256 burnAmount) public {
        vm.assume(burnAmount > 0);
        vm.assume(initialBalance >= burnAmount);
        vm.assume(initialBalance <= type(uint256).max / 2);

        vm.prank(c.owner());
        c.mintToken(address(this), initialBalance);

        uint256 totalSupplyBefore = c.totalSupply();

        vm.prank(address(this));
        c.burn(burnAmount);

        uint256 totalSupplyAfter = c.totalSupply();

        assertTrue(totalSupplyAfter == totalSupplyBefore - burnAmount);
    }
}
